CREATE TABLE "checkpoints" ("id" TEXT PRIMARY KEY, "conversation_id" TEXT NOT NULL CONSTRAINT "checkpoints_conversation_id_fkey" REFERENCES "conversations"("id") ON DELETE CASCADE, "run_id" TEXT, "node_id" TEXT, "path" TEXT NOT NULL, "previous_content" TEXT, "restorable" INTEGER DEFAULT true NOT NULL, "inserted_at" TEXT NOT NULL);
CREATE TABLE "conversations" ("id" TEXT PRIMARY KEY, "project_id" TEXT NOT NULL CONSTRAINT "conversations_project_id_fkey" REFERENCES "projects"("id") ON DELETE CASCADE, "title" TEXT DEFAULT 'New conversation' NOT NULL, "chat_provider_id" TEXT, "chat_model" TEXT, "swarm_provider_id" TEXT, "swarm_model" TEXT, "inserted_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "goal" TEXT, "mode" TEXT DEFAULT 'build' NOT NULL, "queued" TEXT DEFAULT ('[]'), "effort" TEXT, "swarm_effort" TEXT, "last_seen_at" TEXT, "scheduled_task_id" TEXT CONSTRAINT "conversations_scheduled_task_id_fkey" REFERENCES "scheduled_tasks"("id") ON DELETE SET NULL, "ultra" INTEGER DEFAULT false, "authoring_workflow" INTEGER DEFAULT false, "pinned_at" TEXT, "research_id" INTEGER CONSTRAINT "conversations_research_id_fkey" REFERENCES "researches"("id") ON DELETE CASCADE, "consensus" INTEGER DEFAULT false NOT NULL, "consensus_checks" TEXT, "consensus_rounds" INTEGER DEFAULT 2 NOT NULL, "judge_provider_id" TEXT, "judge_model" TEXT, "judge_effort" TEXT, "implementer_provider_id" TEXT, "implementer_model" TEXT, "implementer_effort" TEXT);
CREATE TABLE "goals" ("id" TEXT PRIMARY KEY, "conversation_id" TEXT NOT NULL CONSTRAINT "goals_conversation_id_fkey" REFERENCES "conversations"("id") ON DELETE CASCADE, "text" TEXT NOT NULL, "mode" TEXT DEFAULT 'chat' NOT NULL, "status" TEXT DEFAULT 'active' NOT NULL, "run_id" TEXT, "inserted_at" TEXT NOT NULL, "finished_at" TEXT);
CREATE TABLE "mcp_servers" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "transport" TEXT DEFAULT 'stdio' NOT NULL, "command" TEXT, "args" TEXT DEFAULT ('[]'), "env" TEXT DEFAULT ('{}'), "url" TEXT, "headers" TEXT DEFAULT ('{}'), "enabled" INTEGER DEFAULT true NOT NULL, "project_id" TEXT CONSTRAINT "mcp_servers_project_id_fkey" REFERENCES "projects"("id") ON DELETE CASCADE, "inserted_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL);
CREATE TABLE "messages" ("id" TEXT PRIMARY KEY, "conversation_id" TEXT NOT NULL CONSTRAINT "messages_conversation_id_fkey" REFERENCES "conversations"("id") ON DELETE CASCADE, "role" TEXT NOT NULL, "content" TEXT DEFAULT '', "run_id" TEXT, "tokens_in" INTEGER DEFAULT 0, "tokens_out" INTEGER DEFAULT 0, "cost_usd" NUMERIC, "position" INTEGER DEFAULT 0 NOT NULL, "inserted_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "reasoning" TEXT, "attachments" TEXT DEFAULT ('[]'), "reply_to_run_id" TEXT, "research_ids" TEXT DEFAULT ('[]') NOT NULL);
CREATE TABLE "nodes" ("id" TEXT PRIMARY KEY, "run_id" TEXT NOT NULL CONSTRAINT "nodes_run_id_fkey" REFERENCES "runs"("id") ON DELETE CASCADE, "parent_id" TEXT, "kind" TEXT NOT NULL, "op_type" TEXT, "name" TEXT, "role" TEXT, "title" TEXT DEFAULT '', "status" TEXT DEFAULT 'running' NOT NULL, "progress" INTEGER, "detail" TEXT, "result" TEXT, "error" TEXT, "tokens_in" INTEGER DEFAULT 0, "tokens_out" INTEGER DEFAULT 0, "cost_usd" NUMERIC, "depth" INTEGER DEFAULT 0, "position" INTEGER DEFAULT 0, "started_at" TEXT, "finished_at" TEXT, "inserted_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "turn" INTEGER, "max_turns" INTEGER, "workspace_path" TEXT, "branch" TEXT, "base_sha" TEXT, "changes_stat" TEXT, "integrated" INTEGER DEFAULT false NOT NULL, "phase" TEXT, "group" TEXT, "prompt" TEXT, "input" TEXT);
CREATE TABLE "projects" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "root_path" TEXT NOT NULL, "approval_mode" TEXT DEFAULT 'auto' NOT NULL, "last_opened_at" TEXT, "inserted_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "scratch" INTEGER DEFAULT false NOT NULL);
CREATE TABLE "providers" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "kind" TEXT DEFAULT 'openai_compatible' NOT NULL, "base_url" TEXT NOT NULL, "api_key" TEXT DEFAULT '', "models" TEXT, "default_model" TEXT, "inserted_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "effort_levels" TEXT, "model_effort_levels" TEXT DEFAULT '{}');
CREATE TABLE "research_steps" ("id" TEXT PRIMARY KEY, "research_id" INTEGER NOT NULL CONSTRAINT "research_steps_research_id_fkey" REFERENCES "researches"("id") ON DELETE CASCADE, "index" INTEGER NOT NULL, "title" TEXT, "tasks" TEXT DEFAULT ('[]') NOT NULL, "notes" TEXT DEFAULT ('[]') NOT NULL, "status" TEXT DEFAULT 'pending' NOT NULL, "started_at" TEXT, "finished_at" TEXT, "inserted_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "headline" TEXT);
CREATE TABLE "researches" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "question" TEXT NOT NULL, "level" TEXT DEFAULT 'medium' NOT NULL, "status" TEXT DEFAULT 'queued' NOT NULL, "title" TEXT, "interpretation" TEXT, "summary" TEXT, "step" INTEGER DEFAULT 0 NOT NULL, "steps_total" INTEGER DEFAULT 1 NOT NULL, "fanout" INTEGER DEFAULT 3 NOT NULL, "dir" TEXT, "result_path" TEXT, "report_path" TEXT, "sources" TEXT DEFAULT ('[]') NOT NULL, "tokens_in" INTEGER DEFAULT 0 NOT NULL, "tokens_out" INTEGER DEFAULT 0 NOT NULL, "cost_usd" NUMERIC, "error" TEXT, "run_id" TEXT, "conversation_id" TEXT, "project_id" TEXT CONSTRAINT "researches_project_id_fkey" REFERENCES "projects"("id") ON DELETE SET NULL, "started_at" TEXT, "finished_at" TEXT, "inserted_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "provider_id" TEXT, "model" TEXT, "effort" TEXT, "pinned_at" TEXT, "design_state" TEXT);
CREATE TABLE "runs" ("id" TEXT PRIMARY KEY, "conversation_id" TEXT NOT NULL CONSTRAINT "runs_conversation_id_fkey" REFERENCES "conversations"("id") ON DELETE CASCADE, "kind" TEXT NOT NULL, "status" TEXT DEFAULT 'running' NOT NULL, "prompt" TEXT DEFAULT '', "root_node_id" TEXT, "assistant_message_id" TEXT, "tokens_in" INTEGER DEFAULT 0, "tokens_out" INTEGER DEFAULT 0, "cost_usd" NUMERIC, "started_at" TEXT NOT NULL, "finished_at" TEXT, "inserted_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "interrupted" INTEGER DEFAULT false NOT NULL, "model" TEXT, "goal_id" TEXT, "label" TEXT, "seen_at" TEXT, "launched_by_run_id" TEXT, "consensus" INTEGER DEFAULT false NOT NULL, "consensus_config" TEXT, "resumed_from_run_id" TEXT, "pruned" INTEGER DEFAULT false NOT NULL, "mode" TEXT, "implements_run_id" TEXT, "plan_state" TEXT);
CREATE TABLE "scheduled_runs" ("id" TEXT PRIMARY KEY, "task_id" TEXT NOT NULL CONSTRAINT "scheduled_runs_task_id_fkey" REFERENCES "scheduled_tasks"("id") ON DELETE CASCADE, "conversation_id" TEXT CONSTRAINT "scheduled_runs_conversation_id_fkey" REFERENCES "conversations"("id") ON DELETE SET NULL, "run_id" TEXT, "scheduled_for" TEXT NOT NULL, "started_at" TEXT, "status" TEXT DEFAULT 'running' NOT NULL, "inserted_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL);
CREATE TABLE "scheduled_tasks" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "prompt" TEXT NOT NULL, "kind" TEXT DEFAULT 'chat' NOT NULL, "project_id" TEXT NOT NULL CONSTRAINT "scheduled_tasks_project_id_fkey" REFERENCES "projects"("id") ON DELETE CASCADE, "mode" TEXT DEFAULT 'build' NOT NULL, "schedule_kind" TEXT DEFAULT 'daily' NOT NULL, "run_at" TEXT, "time_of_day" TEXT, "weekdays" TEXT DEFAULT ('[]'), "day_of_month" INTEGER, "cron" TEXT, "timezone" TEXT DEFAULT 'Etc/UTC' NOT NULL, "color" TEXT DEFAULT 'orange' NOT NULL, "enabled" INTEGER DEFAULT true NOT NULL, "catch_up" INTEGER DEFAULT true NOT NULL, "last_run_at" TEXT, "next_run_at" TEXT, "inserted_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "provider_id" TEXT, "model" TEXT, "effort" TEXT, "workflow_name" TEXT, "workflow_args" TEXT DEFAULT '{}');
CREATE TABLE "schema_migrations" ("version" INTEGER PRIMARY KEY, "inserted_at" TEXT);
CREATE TABLE "search_providers" ("id" TEXT PRIMARY KEY, "kind" TEXT NOT NULL, "api_key" TEXT DEFAULT '', "base_url" TEXT, "enabled" INTEGER DEFAULT false NOT NULL, "position" INTEGER DEFAULT 0 NOT NULL, "inserted_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL);
CREATE TABLE "settings" ("id" TEXT PRIMARY KEY, "theme" TEXT DEFAULT 'obsidian' NOT NULL, "mode" TEXT DEFAULT 'dark' NOT NULL, "sidebar_collapsed" INTEGER DEFAULT false NOT NULL, "split_ratio" NUMERIC DEFAULT 0.5 NOT NULL, "tavily_api_key" TEXT, "max_concurrent_agents" INTEGER DEFAULT 4 NOT NULL, "max_agent_depth" INTEGER DEFAULT 2 NOT NULL, "max_agent_turns" INTEGER DEFAULT 40 NOT NULL, "command_timeout_ms" INTEGER DEFAULT 120000 NOT NULL, "default_chat_provider_id" TEXT, "default_chat_model" TEXT, "default_swarm_provider_id" TEXT, "default_swarm_model" TEXT, "pricing" TEXT, "inserted_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "show_reasoning" INTEGER DEFAULT false NOT NULL, "pane_view" TEXT DEFAULT 'cards' NOT NULL, "worktrees_enabled" INTEGER DEFAULT true NOT NULL, "sidebar_width" INTEGER DEFAULT 280 NOT NULL, "reduce_motion" INTEGER DEFAULT false NOT NULL, "default_effort" TEXT DEFAULT 'medium' NOT NULL, "monthly_budget_usd" NUMERIC, "default_swarm_effort" TEXT DEFAULT 'medium', "agents_view" TEXT DEFAULT 'tree', "tool_timeout_ms" INTEGER DEFAULT 120000, "sidebar_sections" TEXT DEFAULT '{}', "sidebar_show_global_tasks" INTEGER DEFAULT true, "agents_density" TEXT DEFAULT 'full', "default_scheduled_provider_id" TEXT, "default_scheduled_model" TEXT, "default_scheduled_effort" TEXT, "workflow_budget" INTEGER DEFAULT 128, "workflow_max_live" INTEGER DEFAULT 16, "default_workflow_provider_id" TEXT, "default_workflow_model" TEXT, "default_workflow_effort" TEXT, "focus_on_finish" INTEGER DEFAULT false, "side_ratio" NUMERIC DEFAULT 0.32 NOT NULL, "side_w_2col" INTEGER DEFAULT 440 NOT NULL, "side_w_3col" INTEGER DEFAULT 380 NOT NULL, "pane_w" INTEGER DEFAULT 420 NOT NULL, "composer_h" INTEGER, "side_composer_h" INTEGER, "prompt_size" TEXT DEFAULT 'md', "research_level" TEXT DEFAULT 'medium' NOT NULL, "research_max_live" INTEGER DEFAULT 6 NOT NULL, "research_max_sources" INTEGER DEFAULT 5 NOT NULL, "research_recency_days" INTEGER, "research_include_domains" TEXT DEFAULT ('[]') NOT NULL, "research_exclude_domains" TEXT DEFAULT ('[]') NOT NULL, "research_reader" TEXT DEFAULT 'web_fetch' NOT NULL, "research_lead_provider_id" TEXT, "research_lead_model" TEXT, "research_lead_effort" TEXT, "research_worker_provider_id" TEXT, "research_worker_model" TEXT, "research_worker_effort" TEXT, "research_reporter_provider_id" TEXT, "research_reporter_model" TEXT, "research_reporter_effort" TEXT, "research_headlines" INTEGER DEFAULT true NOT NULL, "consensus_layout" TEXT DEFAULT 'stacked' NOT NULL, "sidebar_scroll" INTEGER DEFAULT 0 NOT NULL, "research_agent_timeout_s" INTEGER DEFAULT 600 NOT NULL, "research_retry_timeouts" INTEGER DEFAULT true NOT NULL, "research_max_retries" INTEGER DEFAULT 1 NOT NULL, "default_implementer_provider_id" TEXT, "default_implementer_model" TEXT, "default_implementer_effort" TEXT, "research_auto_design" TEXT DEFAULT 'deep' NOT NULL, "storage_retention_days" INTEGER, "storage_prune_days" INTEGER, "storage_last_cleanup_at" TEXT);
CREATE TABLE "workflow_journal" ("id" TEXT PRIMARY KEY, "run_id" TEXT NOT NULL CONSTRAINT "workflow_journal_run_id_fkey" REFERENCES "runs"("id") ON DELETE CASCADE, "seq" INTEGER NOT NULL, "slot" INTEGER NOT NULL, "fingerprint" INTEGER NOT NULL, "kind" TEXT NOT NULL, "result" TEXT, "inserted_at" TEXT NOT NULL);
